package com.portafolio.dt.controller;
import com.portafolio.dt.dto.*; import com.portafolio.dt.repository.UsuarioRepository; import com.portafolio.dt.security.JwtService; import jakarta.validation.Valid; import org.springframework.security.authentication.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthenticationManager auth;private final JwtService jwt;private final UsuarioRepository users;public AuthController(AuthenticationManager a,JwtService j,UsuarioRepository u){auth=a;jwt=j;users=u;}@PostMapping("/login") public LoginResponse login(@Valid @RequestBody LoginRequest r){auth.authenticate(new UsernamePasswordAuthenticationToken(r.username(),r.password()));return new LoginResponse(jwt.generate(r.username()),r.username());}@GetMapping("/me") public Object me(java.security.Principal p){return users.findByUsername(p.getName()).orElseThrow();}}
